165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
169	        // been used for a successful create, return the originally created owner with 200 OK instead
170	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
171	        // with 409). A first, unseen key runs the normal create and records its result under the key.
172	        String idempotencyKey = currentIdempotencyKey();
173	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
174	            return createOwner(ownerFieldsDto);
175	        }
176	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
177	        if (previouslyCreated != null) {
178	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
179	        }
180	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
181	        idempotentCreates.put(idempotencyKey, response.getBody());
182	        return response;
183	    }
