185	    /**
186	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
187	     * the request carries no such header (or there is no active servlet request). Reading it from the
188	     * request context here keeps the header — a request-level concern surrounding the create — out of
189	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
190	     *
191	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
192	     */
193	    private String currentIdempotencyKey() {
194	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
195	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
196	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
197	        }
198	        return null;
199	    }
