201	    /**
202	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
203	     * response for the newly persisted owner: the request fields are mapped and normalized, every
204	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
205	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
206	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
207	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
208	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
209	     * {@code addOwner} without disturbing the creation steps gathered here.
210	     *
211	     * @param ownerFieldsDto the submitted owner fields
212	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
213	     */
214	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
215	        HttpHeaders headers = new HttpHeaders();
216	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
217	        normalizeOwnerFields(owner);
218	        // Enforce the pre-persistence policies that can reject the new owner outright.
219	        rejectDisallowedOwnerCreation(owner);
220	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
221	        // function of last name and postcode), reject a household duplicate unless the request
222	        // declares it shares the household, and record the household size. This runs before the
223	        // identity-key check so that check sees the owner's household id.
224	        boolean declaredHouseholdMember =
225	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
226	        // Reject the create when the owner's whole derived identity key (normalized telephone,
227	        // email and household id) already matches an existing owner. This single rule subsumes the
228	        // former separate telephone, email and household duplicate checks.
229	        rejectWhenIdentityInUse(owner);
230	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
231	        // shares an existing owner's last name and postcode with a different telephone. A declared
232	        // household member is never flagged: it is a known member, not a suspected duplicate.
233	        assignPossibleDuplicate(owner, declaredHouseholdMember);
234	        // Assign the remaining create-time derived fields (namesake count, customer code,
235	        // membership number and bulk-signup warning), each fixed at creation time.
236	        assignDerivedFields(owner);
237	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
238	        // derived fields above because the level is computed from the membership points, which depend
239	        // on the namesake count assigned in assignDerivedFields.
240	        assignMembershipLevel(owner);
241	        this.clinicService.saveOwner(owner);
242	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
243	        // Emit an audit line for the successful create, carrying the owner id, customer code,
244	        // registration date, membership level and membership number so the create can be traced
245	        // from the dedicated AUDIT log.
246	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
247	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
248	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
249	        headers.setLocation(UriComponentsBuilder.newInstance()
250	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
251	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
252	    }
