254	    /**
255	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
256	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
257	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
258	     * the sequence of create-time rejections stays readable and a new rule is added as one more
259	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
260	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
261	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
262	     * the household id has been resolved, because that key includes the household id.
263	     *
264	     * @param owner the newly mapped and normalized owner being created
265	     */
266	    private void rejectDisallowedOwnerCreation(Owner owner) {
267	        rejectWhenDailyLimitReached(owner);
268	        rejectWhenCityAtCapacity(owner);
269	    }
270	
271	    /**
272	     * Applies the household-membership rules for a newly normalized owner being created. The
273	     * household id is a deterministic function of the owner's last name and postcode, so owners
274	     * with the same last name and postcode share it automatically; it is assigned to the new owner
275	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
276	     * same last name and postcode is a member of the same household. A new owner may join an
277	     * existing household: rather than the create being rejected, the newcomer's membership level is
278	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
279	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
280	     * declared member and is never flagged as a possible duplicate. The owner's
281	     * {@code householdSize} (the number of owners sharing the household after this create) is
282	     * recorded either way. The assigned household id is part of the owner's identity key, so it is
283	     * resolved here before {@link #rejectWhenIdentityInUse}.
284	     *
285	     * @param owner           the newly mapped and normalized owner being created
286	     * @param sharesHousehold whether the request declared that the owner shares an existing household
287	     * @return {@code true} if the owner joined an existing household as a declared member
288	     */
289	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
290	        // Assign the deterministic household id (a pure function of last name and postcode) so every
291	        // owner with the same last name and postcode shares it automatically.
292	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
293	        // Identify any existing owners in the same household (same computed household id). A new owner
294	        // may join an existing household: its membership level is capped at one above the household's
295	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
296	        List<Owner> householdMembers = sameHouseholdOwners(owner);
297	        // An owner that joins an existing household while the request declares it shares that
298	        // household is a known, declared member and so is never flagged as a possible duplicate.
299	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
300	        // Record the size of this owner's household after this create, fixed at creation time.
301	        owner.setHouseholdSize(householdMembers.size() + 1);
302	        return declaredHouseholdMember;
303	    }
304	
305	    /**
306	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
307	     * has already been resolved: the namesake count, the per-city customer code, the membership
308	     * number derived from that customer code and the registration fiscal year, and the bulk-signup warning
309	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
310	     * here keeps {@link #addOwner} focused on the high-level create sequence.
311	     *
312	     * @param owner the owner being created, already normalized and with its household resolved
313	     */
314	    private void assignDerivedFields(Owner owner) {
315	        // Record how many existing owners already share this owner's first and last name
316	        // (compared case-insensitively) before this create, fixed at creation time.
317	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
318	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
319	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
320	        // time.
321	        owner.setCustomerCode(customerCode(owner));
322	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
323	        // of the fiscal year of the registration date (e.g. 'NSW-A1B2C3D4-M26'), fixed at
324	        // creation time.
325	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
326	        // Flag the create when more than 80 owners have already been created on this owner's
327	        // (adjusted business-day) registration date, fixed at creation time.
328	        owner.setBulkSignupWarning(
329	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
330	    }
331	
332	    /**
333	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
334	     * time. The level a newly created owner would earn from their membership points cannot exceed
335	     * one above the current maximum membership level among their existing household members (the
336	     * owners already sharing this owner's household id); the capped value is stored so it is returned
337	     * unchanged on later reads. When the owner has no existing household member no cap applies and
338	     * the plain points-derived level is used.
339	     *
340	     * @param owner the owner being created, already normalized and with its derived fields assigned
341	     */
342	    private void assignMembershipLevel(Owner owner) {
343	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
344	        List<Owner> householdMembers = sameHouseholdOwners(owner);
345	        if (!householdMembers.isEmpty()) {
346	            int maxMemberLevel = householdMembers.stream()
347	                .mapToInt(this::memberLevel)
348	                .max()
349	                .getAsInt();
350	            level = Math.min(level, maxMemberLevel + 1);
351	        }
352	        owner.setMembershipLevel(level);
353	    }
354	
355	    /**
356	     * Returns an existing household member's membership level for the purpose of capping a new
357	     * member's level: the level stored on the member when present (the already-capped value fixed at
358	     * its own creation), otherwise the level derived from its membership points (for members created
359	     * before the level was persisted).
360	     *
361	     * @param member an existing owner in the same household
362	     * @return the member's membership level
363	     */
364	    private int memberLevel(Owner member) {
365	        return member.getMembershipLevel() != null
366	            ? member.getMembershipLevel()
367	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
368	    }
369	
370	    /**
371	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
372	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
373	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
374	     * the former separate telephone, email and household duplicate checks: two owners collide only
375	     * when their whole keys are equal, and members of one household with different telephones have
376	     * different keys and are both allowed.
377	     *
378	     * @param owner the owner being created, already normalized and with its household resolved
379	     */
380	    private void rejectWhenIdentityInUse(Owner owner) {
381	        String identityKey = owner.getIdentityKey();
382	        boolean inUse = existingOwners()
383	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
384	        if (inUse) {
385	            throw new DuplicateIdentityException(
386	                "An owner with identity key " + identityKey + " already exists");
387	        }
388	    }
389	
390	    /**
391	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
392	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
393	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
394	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
395	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
396	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
397	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
398	     * possible duplicate. A declared household member is never flagged: it is a known member of the
399	     * household, not a suspected duplicate. Both values are fixed at creation time.
400	     *
401	     * @param owner                   the owner being created, already normalized and confirmed not a
402	     *                                hard duplicate
403	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
404	     *                                member
405	     */
406	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
407	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
408	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
409	            .map(Owner::getId)
410	            .min(Integer::compareTo)
411	            .orElse(null);
412	        owner.setPossibleDuplicate(matchId != null);
413	        owner.setPossibleDuplicateOf(matchId);
414	    }
415	
416	    /**
417	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
418	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
419	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
420	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
421	     *
422	     * @param existing an existing owner to compare against
423	     * @param owner    the owner being created
424	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
425	     */
426	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
427	        return existing.getPostcode() != null
428	            && existing.getPostcode().equals(owner.getPostcode())
429	            && existing.getLastName() != null
430	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
431	            && existing.getTelephone() != null
432	            && !existing.getTelephone().equals(owner.getTelephone());
433	    }
434	
435	    /**
436	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
437	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
438	     *
439	     * @param owner the owner being created
440	     */
441	    private void rejectWhenDailyLimitReached(Owner owner) {
442	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
443	            throw new DailyOwnerLimitExceededException(
444	                "The maximum number of owners that may be created today has already been reached");
445	        }
446	    }
447	
448	    /**
449	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
450	     * or more owners, with 409 Conflict.
451	     *
452	     * @param owner the owner being created
453	     */
454	    private void rejectWhenCityAtCapacity(Owner owner) {
455	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
456	            throw new CityCapacityExceededException(
457	                "The city " + owner.getCity() + " already contains the maximum number of owners");
458	        }
459	    }
460	
461	    /**
462	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
463	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
464	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
465	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
466	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
467	     * server's current date. Canonicalising the address here, before the household checks read it,
468	     * ensures duplicate detection and the shared household id both compare the normalized form.
469	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
470	     * duplicate, household and customer-code rules.
471	     *
472	     * @param owner the newly mapped owner to canonicalize
473	     */
474	    private void normalizeOwnerFields(Owner owner) {
475	        // Canonicalize the owner's address fields on create so the address is stored and returned in
476	        // canonical form and every later comparison (household duplicate detection and the shared
477	        // household id) uses it. A value that is blank after normalization is rejected with 400.
478	        normalizeAddressFields(owner);
479	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
480	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
481	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
482	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
483	        // Store the (already syntactically validated) email lower-cased so it is persisted and
484	        // returned in canonical form. A missing email is left untouched.
485	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
486	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
487	        // canonicalization so the comparison sees the lower-cased value.
488	        rejectDisposableEmailDomain(owner.getEmail());
489	        // Validate the optional postcode against the fixed range for the city's region. A postcode
490	        // is checked only when present (it is optional); one out of range for the city's region is
491	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
492	        // value is left unchanged.
493	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
494	        // Reject a supplied registration date that is later than the server's current date with
495	        // 400, before any defaulting or business-day adjustment, so a future date is never
496	        // persisted regardless of how the roll-forward would move it.
497	        rejectFutureRegistrationDate(owner.getRegistrationDate());
498	        // Default the registration date to the server's current date when the client did not
499	        // supply one, then roll the effective date forward to a business day so a Saturday or
500	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
501	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
502	        // date-derived field (such as the membership number's year segment) and the per-day
503	        // create-limit are computed from.
504	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
505	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
506	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
507	    }
508	
509	    /**
510	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
511	     * returned in canonical form. The owner may supply its address in either of two forms and the
512	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
513	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
514	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
515	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
516	     * stored {@code address} is composed from the normalized structured lines when present — the
517	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
518	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
519	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
520	     * here, before the household checks read it, ensures duplicate detection and the shared household
521	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
522	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
523	     *
524	     * @param owner the newly mapped owner whose address is canonicalized
525	     */
526	    private void normalizeAddressFields(Owner owner) {
527	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
528	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
529	            owner.setAddressLine1(line1);
530	            String composed = line1;
531	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
532	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
533	                owner.setAddressLine2(line2);
534	                composed = line1 + " " + line2;
535	            }
536	            owner.setAddress(composed);
537	        }
538	        else {
539	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
540	        }
541	    }
542	
543	    /**
544	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
545	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
546	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
547	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
548	     * domain part is left untouched.
549	     *
550	     * @param email the owner's canonicalized email, or {@code null} when absent
551	     */
552	    private void rejectDisposableEmailDomain(String email) {
553	        if (email == null) {
554	            return;
555	        }
556	        int at = email.lastIndexOf('@');
557	        if (at < 0) {
558	            return;
559	        }
560	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
561	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
562	            throw new DisposableEmailException(
563	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
564	        }
565	    }
566	
567	    /**
568	     * Rejects a supplied registration date that is later than the server's current date with a
569	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
570	     * accepted, and a date on or before today is left for the normal defaulting and business-day
571	     * adjustment.
572	     *
573	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
574	     */
575	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
576	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
577	            throw new InvalidRegistrationDateException(
578	                "The supplied registration date " + registrationDate + " is later than the current date");
579	        }
580	    }
581	
582	    /**
583	     * The fixed list of public holidays. A registration date that lands on one of these dates is
584	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
585	     */
586	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
587	        java.time.LocalDate.of(2026, 1, 1),
588	        java.time.LocalDate.of(2026, 1, 26),
589	        java.time.LocalDate.of(2026, 4, 25),
590	        java.time.LocalDate.of(2026, 12, 25),
591	        java.time.LocalDate.of(2026, 12, 28));
592	
593	    /**
594	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
595	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
596	     * unchanged. Applied to the effective registration date (whether supplied in the request or
597	     * defaulted to the server date) so the persisted registration date, every value derived from it
598	     * and the per-day create-limit all use the adjusted business day.
599	     *
600	     * @param date the effective registration date
601	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
602	     */
603	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
604	        java.time.LocalDate adjusted = date;
605	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
606	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
607	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
608	            adjusted = adjusted.plusDays(1);
609	        }
610	        return adjusted;
611	    }
612	
613	    /**
614	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
615	     * region derived from the owner's postcode (falling back to the city, via
616	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
617	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
618	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
619	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
620	     * distinct customer codes.
621	     *
622	     * @param owner the owner being created, already normalized
623	     * @return the formatted, de-duplicated customer code
624	     */
625	    private String customerCode(Owner owner) {
626	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
627	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
628	        String base = region + "-" + hash8;
629	        Set<String> taken = existingOwners()
630	            .map(Owner::getCustomerCode)
631	            .filter(code -> code != null)
632	            .collect(Collectors.toSet());
633	        if (!taken.contains(base)) {
634	            return base;
635	        }
636	        int n = 2;
637	        while (taken.contains(base + "-" + n)) {
638	            n++;
639	        }
640	        return base + "-" + n;
641	    }
642	
643	    /**
644	     * Streams the existing owners that the create-time rules match a new owner against. Every
645	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
646	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
647	     * own matching criterion rather than on how the existing owners are retrieved.
648	     *
649	     * @return a stream over all existing owners
650	     */
651	    private Stream<Owner> existingOwners() {
652	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
653	        // new create, so the duplicate, identity and household checks (and the other create-time
654	        // scans built on this helper) ignore it.
655	        return this.clinicService.findAllOwners().stream()
656	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
657	    }
658	
659	    /**
660	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
661	     * fix the per-city sequence of an owner's customer code at creation time.
662	     *
663	     * @param city the city of the owner being created
664	     * @return the number of existing owners in a matching city
665	     */
666	    private int countOwnersInCity(String city) {
667	        return (int) existingOwners()
668	            .filter(existing -> existing.getCity() != null
669	                && existing.getCity().equalsIgnoreCase(city))
670	            .count();
671	    }
672	
673	    /**
674	     * Counts the existing owners whose registration date is the given adjusted business day. Used
675	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
676	     * owners already carry that business day as their registration date.
677	     *
678	     * @param date the adjusted business-day registration date to match
679	     * @return the number of existing owners registered on that date
680	     */
681	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
682	        return (int) existingOwners()
683	            .filter(existing -> date.equals(existing.getRegistrationDate()))
684	            .count();
685	    }
686	
687	    /**
688	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
689	     * the last two digits of the fiscal year of the (business-day-adjusted) registration date
690	     * (e.g. 'NSW-A1B2C3D4-M26'). The fiscal year starts on 1 July, so a registration date on or
691	     * after 1 July carries the following calendar year's fiscal year.
692	     *
693	     * @param customerCode     the owner's customer code
694	     * @param registrationDate the owner's registration date
695	     * @return the formatted membership number
696	     */
697	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
698	        return String.format("%s-M%02d",
699	            customerCode, org.springframework.samples.petclinic.util.FiscalYear.of(registrationDate) % 100);
700	    }
701	
702	    /**
703	     * Returns the existing owners in the given owner's household, i.e. those sharing its
704	     * deterministic household id (the same last name and postcode). The id is computed via
705	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
706	     * whitespace are treated as the same household. Centralising how "the same household" is matched
707	     * here keeps that definition in one place for every caller.
708	     *
709	     * @param owner the owner being created, with its household id already assigned
710	     * @return the existing owners in the owner's household (possibly empty)
711	     */
712	    private List<Owner> sameHouseholdOwners(Owner owner) {
713	        String householdId = owner.getHouseholdId();
714	        return existingOwners()
715	            .filter(existing -> householdId.equals(
716	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
717	            .toList();
718	    }
719	
720	    /**
721	     * Counts the existing owners who share the given first and last name, compared
722	     * case-insensitively. Used to fix an owner's namesake count at creation time.
723	     *
724	     * @param firstName the first name of the owner being created
725	     * @param lastName  the last name of the owner being created
726	     * @return the number of existing owners with a matching first and last name
727	     */
728	    private int countNamesakes(String firstName, String lastName) {
729	        return (int) existingOwners()
730	            .filter(existing -> existing.getFirstName() != null
731	                && existing.getFirstName().equalsIgnoreCase(firstName)
732	                && existing.getLastName() != null
733	                && existing.getLastName().equalsIgnoreCase(lastName))
734	            .count();
735	    }
736	
737	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
738	    @Override
739	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
740	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
741	        if (currentOwner == null) {
742	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
743	        }
744	        currentOwner.setAddress(ownerFieldsDto.getAddress());
745	        currentOwner.setCity(ownerFieldsDto.getCity());
746	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
747	        currentOwner.setLastName(ownerFieldsDto.getLastName());
748	        // Normalize the telephone to canonical E.164 form so it is stored and returned
749	        // consistently with create; an unformattable value is rejected with 400.
750	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
751	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
752	        this.clinicService.saveOwner(currentOwner);
753	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
754	    }
755	
756	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
757	    @Transactional
758	    @Override
759	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
760	        Owner owner = this.clinicService.findOwnerById(ownerId);
761	        if (owner == null) {
762	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
763	        }
764	        // Soft-delete: flag the owner as deleted and retain the row rather than removing it, so the
765	        // owner is still returned by GET (with 'deleted' true) and only excluded from the create-time
766	        // duplicate and identity checks (see existingOwners()).
767	        owner.setDeleted(true);
768	        this.clinicService.saveOwner(owner);
769	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
770	    }
771	
772	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
773	    @Override
774	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
775	        Owner owner = this.clinicService.findOwnerById(ownerId);
776	        if (owner == null) {
777	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
778	        }
779	        HttpHeaders headers = new HttpHeaders();
780	        Pet pet = petMapper.toPet(petFieldsDto);
781	        owner.setId(ownerId);
782	        pet.setOwner(owner);
783	        pet.getType().setName(null);
784	        this.clinicService.savePet(pet);
785	        PetDto petDto = petMapper.toPetDto(pet);
786	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
787	            .buildAndExpand(pet.getId()).toUri());
788	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
789	    }
790	
791	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
792	    @Override
793	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
794	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
795	        if (currentOwner != null) {
796	            Pet currentPet = this.clinicService.findPetById(petId);
797	            if (currentPet != null) {
798	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
799	                currentPet.setName(petFieldsDto.getName());
800	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
801	                this.clinicService.savePet(currentPet);
802	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
803	            }
804	        }
805	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
806	    }
807	
808	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
809	    @Override
810	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
811	        HttpHeaders headers = new HttpHeaders();
812	        Visit visit = visitMapper.toVisit(visitFieldsDto);
813	        Pet pet = new Pet();
814	        pet.setId(petId);
815	        visit.setPet(pet);
816	        this.clinicService.saveVisit(visit);
817	        VisitDto visitDto = visitMapper.toVisitDto(visit);
818	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
819	            .buildAndExpand(visit.getId()).toUri());
820	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
821	    }
822	
823	
824	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
825	    @Override
826	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
827	        Owner owner = this.clinicService.findOwnerById(ownerId);
828	        if (owner != null) {
829	            Pet pet = owner.getPet(petId);
830	            if (pet != null) {
831	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
832	            }
833	        }
834	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
835	    }
836	}
